# Shared helpers for the Facebook and Instagram posting scripts (dot-sourced).

$script:repo = Split-Path -Parent $PSScriptRoot
$script:logDir = Join-Path $PSScriptRoot 'logs'
$script:graphVersion = 'v23.0'
$script:secretsFile = Join-Path $env:USERPROFILE '.qurevanta\facebook.json'

function Escape-CloudinaryText([string]$text) {
  $encoded = [uri]::EscapeDataString($text)
  return $encoded.Replace('%2C', '%252C').Replace('%2F', '%252F').Replace('%3A', '%253A')
}

# 1080x1350 JPEG: article photo + dark overlay + category, bold title and qurevanta.com (generated by Cloudinary)
function Get-SocialImageUrl([string]$imageUrl, [string]$title, [string]$category) {
  $layers = @(
    'c_fill,g_auto,w_1080,h_1350',
    'co_rgb:000000,e_colorize:62',
    "l_text:Montserrat_34_bold_letter_spacing_6:$(Escape-CloudinaryText $category.ToUpper()),co_rgb:D4F26D/fl_layer_apply,g_north_west,x_80,y_110",
    "l_text:Montserrat_84_bold_line_spacing_-6:$(Escape-CloudinaryText $title),co_white,c_fit,w_920/fl_layer_apply,g_west,x_80,y_-40",
    "l_text:Montserrat_34:$(Escape-CloudinaryText 'Read the full guide'),co_rgb:C9D6CF/fl_layer_apply,g_south_west,x_80,y_150",
    "l_text:Montserrat_44_bold:$(Escape-CloudinaryText 'qurevanta.com'),co_rgb:D4F26D/fl_layer_apply,g_south_west,x_80,y_85",
    'f_jpg,q_auto'
  ) -join '/'
  if ($imageUrl -match '^https://res\.cloudinary\.com/dr3ie9gpz/image/upload/(?:[^/]*_[^/]*/)*(v\d+/.+)$') {
    return "https://res.cloudinary.com/dr3ie9gpz/image/upload/$layers/$($Matches[1])"
  }
  return "https://res.cloudinary.com/dr3ie9gpz/image/fetch/$layers/$([uri]::EscapeDataString($imageUrl))"
}

# Reads automation/logs/latest-article.json and the article's frontmatter
function Get-LatestArticle {
  $info = Get-Content (Join-Path $script:logDir 'latest-article.json') -Raw -Encoding UTF8 | ConvertFrom-Json
  $front = @{}
  foreach ($line in (Get-Content (Join-Path $script:repo "src\content\blog\$($info.slug).md") -Encoding UTF8)) {
    if ($line -eq '---' -and $front.Count) { break }
    if ($line -match '^(\w+):\s*(.*)$') { $front[$Matches[1]] = $Matches[2] }
  }
  $title = if ($info.socialTitle) { $info.socialTitle } else { $front['title'] }
  [pscustomobject]@{
    Slug     = $info.slug
    Url      = "https://www.qurevanta.com/resources/$($info.slug)"
    Caption  = "$($info.caption)".Trim()
    IgCaption = "$($info.instagramCaption)".Trim()
    ImageUrl = Get-SocialImageUrl $front['image'] $title $front['category']
  }
}

function Get-Secrets {
  if (-not (Test-Path $script:secretsFile)) { throw "Meta credentials not found at $script:secretsFile" }
  return Get-Content $script:secretsFile -Raw | ConvertFrom-Json
}

function Test-AlreadyPosted([string]$network, [string]$slug) {
  $marker = Join-Path $script:logDir "$network-posted.txt"
  return (Test-Path $marker) -and ((Get-Content $marker | ForEach-Object { $_.Trim() }) -contains $slug)
}

function Set-Posted([string]$network, [string]$slug) {
  Add-Content -Path (Join-Path $script:logDir "$network-posted.txt") -Value $slug
}

# POST to the Graph API as UTF-8 form data (keeps emoji intact on Windows PowerShell 5.1)
function Invoke-GraphPost([string]$path, [hashtable]$form) {
  $body = ($form.GetEnumerator() | ForEach-Object { "$($_.Key)=$([uri]::EscapeDataString([string]$_.Value))" }) -join '&'
  return Invoke-RestMethod -Method Post -Uri "https://graph.facebook.com/$script:graphVersion/$path" `
    -ContentType 'application/x-www-form-urlencoded; charset=utf-8' -Body ([System.Text.Encoding]::UTF8.GetBytes($body))
}

function Wait-ArticleLive([string]$url) {
  for ($i = 0; $i -lt 40; $i++) {
    try { if ((Invoke-WebRequest -Uri $url -Method Head -UseBasicParsing).StatusCode -eq 200) { return } } catch { }
    Start-Sleep -Seconds 15
  }
}
